// ====================================================
// Zero-Undefined Inheritance & Fallback Engine
// Guarantees every single key in any regional language
// falls back cleanly to English if missing or undefined.
// ====================================================
(function ensureLanguageInheritance() {
  const en = TRANSLATIONS['en'];
  if (!en) return;
  const enKeys = Object.keys(en);

  Object.keys(TRANSLATIONS).forEach(lang => {
    if (lang === 'en') return;
    const target = TRANSLATIONS[lang];

    // 1. Inherit all missing top-level UI keys
    enKeys.forEach(key => {
      if (target[key] === undefined || target[key] === null) {
        target[key] = en[key];
      }
    });

    // 2. Ensure nested options dictionaries inherit
    if (!target.options) {
      target.options = JSON.parse(JSON.stringify(en.options));
    } else {
      ['category', 'gender', 'sector', 'state', 'education'].forEach(sub => {
        if (!target.options[sub]) {
          target.options[sub] = en.options[sub];
        } else {
          Object.keys(en.options[sub] || {}).forEach(optKey => {
            if (target.options[sub][optKey] === undefined) {
              target.options[sub][optKey] = en.options[sub][optKey];
            }
          });
        }
      });
    }

    // 3. Ensure criteria & verdicts dictionaries inherit
    if (!target.criteria) target.criteria = Object.assign({}, en.criteria);
    else {
      Object.keys(en.criteria || {}).forEach(k => {
        if (target.criteria[k] === undefined) target.criteria[k] = en.criteria[k];
      });
    }

    if (!target.verdicts) target.verdicts = Object.assign({}, en.verdicts);
    else {
      Object.keys(en.verdicts || {}).forEach(k => {
        if (target.verdicts[k] === undefined) target.verdicts[k] = en.verdicts[k];
      });
    }

    // 4. Ensure schemes & docNames maps exist
    if (!target.schemes) target.schemes = {};
    if (!target.docNames) target.docNames = {};
  });
})();
